    "std_string(result);\n        return v;\n    }\n}\n\n/* exit_code() - return 0 always, the actual exit is handled by the"
    "\n * existing `exit(n)` builtin. Provided for symmetry with the API spec. */\nstatic LAMO_UNUSED LamoValue lamo_process_"
    "exit(LamoValue code) {\n    exit((int)lamo_as_int(code));\n    return lamo_make_int(0);\n}\n\n/* ======================="
    "=========================================== */\n/* std.random \20024 random number generation                           "
    "    */\n/* ================================================================== */\n\n/* Simple xorshift64* PRNG, seeded f"
    "rom time + pid. Not cryptographic. */\nstatic unsigned long long lamo_random_state = 0;\nstatic int lamo_random_seeded ="
    " 0;\n\nstatic LAMO_UNUSED void lamo_random_seed_if_needed(void) {\n    if (!lamo_random_seeded) {\n        lamo_random_s"
    "tate = (unsigned long long)time(NULL);\n        lamo_random_state ^= (unsigned long long)\n#if defined(_WIN32)\n        "
    "    GetCurrentProcessId();\n#else\n            getpid();\n#endif\n        lamo_random_state |= 1; /* ensure non-zero */"
    "\n        lamo_random_seeded = 1;\n    }\n}\n\nstatic LAMO_UNUSED LamoValue lamo_random_seed(LamoValue s) {\n    lamo_ra"
    "ndom_state = (unsigned long long)lamo_as_int(s);\n    if (lamo_random_state == 0) lamo_random_state = 1;\n    lamo_rando"
    "m_seeded = 1;\n    return lamo_make_int(0);\n}\n\nstatic LAMO_UNUSED unsigned long long lamo_random_next(void) {\n    un"
    "signed long long x = lamo_random_state;\n    x ^= x << 13;\n    x ^= x >> 7;\n    x ^= x << 17;\n    lamo_random_state ="
    " x;\n    return x;\n}\n\nstatic LAMO_UNUSED LamoValue lamo_random_int(LamoValue lo, LamoValue hi) {\n    long long low ="
    " lamo_as_int(lo);\n    long long high = lamo_as_int(hi);\n    long long range, r;\n    lamo_random_seed_if_needed();\n  "
    "  if (high < low) { long long t = low; low = high; high = t; }\n    range = high - low + 1;\n    if (range <= 0) return "
    "lamo_make_int(low);\n    r = (long long)(lamo_random_next() % (unsigned long long)range);\n    return lamo_make_int(low "
    "+ r);\n}\n\nstatic LAMO_UNUSED LamoValue lamo_random_float(void) {\n    lamo_random_seed_if_needed();\n    /* Map to [0."
    "0, 1.0). */\n    double v = (double)(lamo_random_next() >> 11) / (double)(1ULL << 53);\n    return lamo_make_float(v);\n"
    "}\n\nstatic LAMO_UNUSED LamoValue lamo_random_bool(void) {\n    lamo_random_seed_if_needed();\n    return lamo_make_bool"
    "((int)(lamo_random_next() & 1));\n}\n\nstatic LAMO_UNUSED LamoValue lamo_random_choice(LamoValue arr) {\n    LamoArray* "
    "a;\n    long long idx;\n    if (arr.type != LAMO_VALUE_ARRAY) {\n        lamo_runtime_type_error(\"random.choice: expect"
    "ed array\");\n    }\n    a = arr.array_value;\n    if (!a || a->count == 0) {\n        lamo_runtime_type_error(\"random."
    "choice: empty array\");\n    }\n    lamo_random_seed_if_needed();\n    idx = (long long)(lamo_random_next() % (unsigned "
    "long long)a->count);\n    return a->items[idx];\n}\n\nstatic LAMO_UNUSED LamoValue lamo_random_shuffle(LamoValue arr) {"
    "\n    /* Fisher-Yates shuffle, in place. */\n    LamoArray* a;\n    long long i;\n    if (arr.type != LAMO_VALUE_ARRAY) "
    "{\n        lamo_runtime_type_error(\"random.shuffle: expected array\");\n    }\n    a = arr.array_value;\n    if (!a) re"
    "turn arr;\n    lamo_random_seed_if_needed();\n    for (i = a->count - 1; i > 0; i--) {\n        long long j = (long long"
    ")(lamo_random_next() % (unsigned long long)(i + 1));\n        LamoValue tmp = a->items[i];\n        a->items[i] = a->ite"
    "ms[j];\n        a->items[j] = tmp;\n    }\n    return arr;\n}\n\n/* ===================================================="
    "============== */\n/* std.io \20024 additional I/O builtins                                    */\n/* =================="
    "================================================ */\n\nstatic LAMO_UNUSED LamoValue lamo_io_println(LamoValue v) {\n    "
    "lamo_print_value(v);\n    return lamo_make_int(0);\n}\n\nstatic LAMO_UNUSED LamoValue lamo_io_eprint(LamoValue v) {\n   "
    " if (v.type == LAMO_VALUE_STRING) {\n        fprintf(stderr, \"%s\\n\", v.string_value ? v.string_value : \"\");\n    } "
    "else if (v.type == LAMO_VALUE_FLOAT) {\n        fprintf(stderr, \"%g\\n\", v.float_value);\n    } else {\n        fprint"
    "f(stderr, \"%lld\\n\", v.int_value);\n    }\n    return lamo_make_int(0);\n}\n\nstatic LAMO_UNUSED LamoValue lamo_io_rea"
    "d_line(void) {\n    /* Read a line from stdin (without prompt). */\n    return lamo_input_str_value(lamo_make_string(\""
    "\"));\n}\n\nstatic LAMO_UNUSED LamoValue lamo_io_write(LamoValue v) {\n    /* Print without trailing newline. */\n    if"
    " (v.type == LAMO_VALUE_STRING) {\n        printf(\"%s\", v.string_value ? v.string_value : \"\");\n    } else if (v.type"
    " == LAMO_VALUE_FLOAT) {\n        printf(\"%g\", v.float_value);\n    } else if (v.type == LAMO_VALUE_BOOL) {\n        pr"
    "intf(\"%s\", v.int_value ? \"true\" : \"false\");\n    } else {\n        printf(\"%lld\", v.int_value);\n    }\n    fflu"
    "sh(stdout);\n    return lamo_make_int(0);\n}\n\n/* ================================================================== */"
    "\n/* std.net \20024 HTTP client (simple, blocking)                            */\n/* ==================================="
    "=============================== */\n\n/* http_get(url) -> string (response body, on success; \"\" on failure). */\nstati"
    "c LAMO_UNUSED LamoValue lamo_net_http_get(LamoValue url_v) {\n    const char* url = lamo_as_cstring(url_v);\n    const c"
    "har* host_start, *path_start, *port_start;\n    char host[256];\n    char path[2048];\n    int port = 80;\n    /* Parse:"
    " http://host[:port]/path */\n    if (strncmp(url, \"http://\", 7) != 0) {\n        fprintf(stderr, \"runtime error: http"
    "_get: only http:// is supported (got '%s')\\n\", url);\n        return lamo_make_string(\"\");\n    }\n    host_start = "
    "url + 7;\n    path_start = strchr(host_start, '/');\n    port_start = strchr(host_start, ':');\n    if (port_start && (!"
    "path_start || port_start < path_start)) {\n        size_t host_len = (size_t)(port_start - host_start);\n        if (hos"
    "t_len >= sizeof(host)) host_len = sizeof(host) - 1;\n        memcpy(host, host_start, host_len);\n        host[host_len]"
    " = '\\0';\n        port = atoi(port_start + 1);\n    } else {\n        size_t host_len = path_start ? (size_t)(path_star"
    "t - host_start) : strlen(host_start);\n        if (host_len >= sizeof(host)) host_len = sizeof(host) - 1;\n        memcp"
    "y(host, host_start, host_len);\n        host[host_len] = '\\0';\n    }\n    if (path_start) {\n        strncpy(path, pat"
    "h_start, sizeof(path) - 1);\n        path[sizeof(path) - 1] = '\\0';\n    } else {\n        strcpy(path, \"/\");\n    }"
    "\n    /* Connect. */\n    {\n#if defined(_WIN32)\n        WSADATA wsa;\n        SOCKET sock;\n        struct sockaddr_in"
    " addr;\n        struct hostent* he;\n        /* request buffer must fit: format (~72 chars) + path (2048) + host (256)."
    "\n         * 4096 gives plenty of headroom and silences -Wformat-truncation. */\n        char request[4096];\n        ch"
    "ar* body;\n        if (WSAStartup(MAKEWORD(2,2), &wsa) != 0) return lamo_make_string(\"\");\n        sock = socket(AF_IN"
    "ET, SOCK_STREAM, 0);\n        if (sock == INVALID_SOCKET) { WSACleanup(); return lamo_make_string(\"\"); }\n        he ="
    " gethostbyname(host);\n        if (!he) { closesocket(sock); WSACleanup(); return lamo_make_string(\"\"); }\n        add"
    "r.sin_family = AF_INET;\n        addr.sin_port = htons((unsigned short)port);\n        addr.sin_addr = *((struct in_addr"
    "*)he->h_addr);\n        if (connect(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {\n            closesocket(sock); "
    "WSACleanup(); return lamo_make_string(\"\");\n        }\n        snprintf(request, sizeof(request),\n                 \""
    "GET %s HTTP/1.1\\r\\nHost: %s\\r\\nConnection: close\\r\\nUser-Agent: lamo-http/1.0\\r\\n\\r\\n\",\n                 pat"
    "h, host);\n        send(sock, request, (int)strlen(request), 0);\n        /* Read response into a heap-growing buffer. *"
    "/\n        {\n            char* buf = NULL;\n            size_t buf_len = 0, buf_cap = 0;\n            char chunk[4096];"
    "\n            int chunk_n;\n            while ((chunk_n = recv(sock, chunk, sizeof(chunk), 0)) > 0) {\n                i"
    "f (buf_len + chunk_n + 1 > buf_cap) {\n                    while (buf_len + chunk_n + 1 > buf_cap) buf_cap = buf_cap ? b"
    "uf_cap * 2 : 8192;\n                    buf = (char*)realloc(buf, buf_cap);\n                }\n                memcpy(b"
    "uf + buf_len, chunk, chunk_n);\n                buf_len += chunk_n;\n            }\n            closesocket(sock); WSACl"
    "eanup();\n            if (!buf) return lamo_make_string(\"\");\n            buf[buf_len] = '\\0';\n            /* Find b"
    "ody (after \\r\\n\\r\\n). */\n            body = strstr(buf, \"\\r\\n\\r\\n\");\n            if (!body) { free(buf); ret"
    "urn lamo_make_string(\"\"); }\n            body += 4;\n            {\n                LamoValue v = lamo_std_string(strd"
    "up(body));\n                free(buf);\n                return v;\n            }\n        }\n#else\n        int sock;\n "
    "       struct sockaddr_in addr;\n        struct hostent* he;\n        /* request buffer must fit: format (~72 chars) + p"
    "ath (2048) + host (256).\n         * 4096 gives plenty of headroom and silences -Wformat-truncation. */\n        char re"
    "quest[4096];\n        char chunk[4096];\n        char* buf = NULL;\n        size_t buf_len = 0, buf_cap = 0;\n        in"
    "t chunk_n;\n        char* body;\n        sock = socket(AF_INET, SOCK_STREAM, 0);\n        if (sock < 0) return lamo_make"
    "_string(\"\");\n        he = gethostbyname(host);\n        if (!he) { close(sock); return lamo_make_string(\"\"); }\n   "
    "     addr.sin_family = AF_INET;\n        addr.sin_port = htons((unsigned short)port);\n        addr.sin_addr = *((struct"
    " in_addr*)he->h_addr);\n        if (connect(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {\n            close(sock)"
    "; return lamo_make_string(\"\");\n        }\n        snprintf(request, sizeof(request),\n                 \"GET %s HTTP/"
    "1.1\\r\\nHost: %s\\r\\nConnection: close\\r\\nUser-Agent: lamo-http/1.0\\r\\n\\r\\n\",\n                 path, host);\n "
    "       send(sock, request, strlen(request), 0);\n        while ((chunk_n = recv(sock, chunk, sizeof(chunk), 0)) > 0) {\n"
    "            if (buf_len + chunk_n + 1 > buf_cap) {\n                while (buf_len + chunk_n + 1 > buf_cap) buf_cap = bu"
    "f_cap ? buf_cap * 2 : 8192;\n                buf = (char*)realloc(buf, buf_cap);\n            }\n            memcpy(buf "
    "+ buf_len, chunk, chunk_n);\n            buf_len += chunk_n;\n        }\n        close(sock);\n        if (!buf) return "
    "lamo_make_string(\"\");\n        buf[buf_len] = '\\0';\n        body = strstr(buf, \"\\r\\n\\r\\n\");\n        if (!body"
    ") { free(buf); return lamo_make_string(\"\"); }\n        body += 4;\n        {\n            LamoValue v = lamo_std_strin"
    "g(strdup(body));\n            free(buf);\n            return v;\n        }\n#endif\n    }\n}\n\n/* http_post(url, body) "
    "-> string (response body). */\nstatic LAMO_UNUSED LamoValue lamo_net_http_post(LamoValue url_v, LamoValue body_v) {\n   "
    " const char* url = lamo_as_cstring(url_v);\n    const char* body = lamo_as_cstring(body_v);\n    char host[256];\n    ch"
    "ar path[2048];\n    int port = 80;\n    const char* host_start, *path_start, *port_start;\n    if (strncmp(url, \"http:/"
    "/\", 7) != 0) {\n        fprintf(stderr, \"runtime error: http_post: only http:// is supported\\n\");\n        return la"
    "mo_make_string(\"\");\n    }\n    host_start = url + 7;\n    path_start = strchr(host_start, '/');\n    port_start = str"
    "chr(host_start, ':');\n    if (port_start && (!path_start || port_start < path_start)) {\n        size_t host_len = (siz"
    "e_t)(port_start - host_start);\n        if (host_len >= sizeof(host)) host_len = sizeof(host) - 1;\n        memcpy(host,"
    " host_start, host_len);\n        host[host_len] = '\\0';\n        port = atoi(port_start + 1);\n    } else {\n        si"
    "ze_t host_len = path_start ? (size_t)(path_start - host_start) : strlen(host_start);\n        if (host_len >= sizeof(hos"
    "t)) host_len = sizeof(host) - 1;\n        memcpy(host, host_start, host_len);\n        host[host_len] = '\\0';\n    }\n "
    "   if (path_start) {\n        strncpy(path, path_start, sizeof(path) - 1);\n        path[sizeof(path) - 1] = '\\0';\n   "
    " } else {\n        strcpy(path, \"/\");\n    }\n    {\n#if defined(_WIN32)\n        /* Similar to GET but with POST and "
    "Content-Length. */\n        WSADATA wsa;\n        SOCKET sock;\n        struct sockaddr_in addr;\n        struct hostent"
    "* he;\n        char request[4096];\n        if (WSAStartup(MAKEWORD(2,2), &wsa) != 0) return lamo_make_string(\"\");\n  "
    "      sock = socket(AF_INET, SOCK_STREAM, 0);\n        if (sock == INVALID_SOCKET) { WSACleanup(); return lamo_make_stri"
    "ng(\"\"); }\n        he = gethostbyname(host);\n        if (!he) { closesocket(sock); WSACleanup(); return lamo_make_str"
    "ing(\"\"); }\n        addr.sin_family = AF_INET;\n        addr.sin_port = htons((unsigned short)port);\n        addr.sin"
    "_addr = *((struct in_addr*)he->h_addr);\n        if (connect(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {\n      "
    "      closesocket(sock); WSACleanup(); return lamo_make_string(\"\");\n        }\n        snprintf(request, sizeof(reque"
    "st),\n                 \"POST %s HTTP/1.1\\r\\nHost: %s\\r\\nContent-Type: text/plain\\r\\nContent-Length: %zu\\r\\nConn"
    "ection: close\\r\\nUser-Agent: lamo-http/1.0\\r\\n\\r\\n%s\",\n                 path, host, strlen(body), body);\n      "
    "  send(sock, request, (int)strlen(request), 0);\n        {\n            char* buf = NULL;\n            size_t buf_len = "
    "0, buf_cap = 0;\n            char chunk[4096];\n            int chunk_n;\n            char* resp_body;\n            whil"
    "e ((chunk_n = recv(sock, chunk, sizeof(chunk), 0)) > 0) {\n                if (buf_len + chunk_n + 1 > buf_cap) {\n     "
    "               while (buf_len + chunk_n + 1 > buf_cap) buf_cap = buf_cap ? buf_cap * 2 : 8192;\n                    buf "
    "= (char*)realloc(buf, buf_cap);\n                }\n                memcpy(buf + buf_len, chunk, chunk_n);\n            "
    "    buf_len += chunk_n;\n            }\n            closesocket(sock); WSACleanup();\n            if (!buf) return lamo_"
    "make_string(\"\");\n            buf[buf_len] = '\\0';\n            resp_body = strstr(buf, \"\\r\\n\\r\\n\");\n         "
    "   if (!resp_body) { free(buf); return lamo_make_string(\"\"); }\n            resp_body += 4;\n            {\n          "
    "      LamoValue v = lamo_std_string(strdup(resp_body));\n                free(buf);\n                return v;\n        "
    "    }\n        }\n#else\n        int sock;\n        struct sockaddr_in addr;\n        struct hostent* he;\n        char*"
    " request = NULL;\n        size_t req_len;\n        char* buf = NULL;\n        size_t buf_len = 0, buf_cap = 0;\n        "
    "char chunk[4096];\n        int chunk_n;\n        char* resp_body;\n        sock = socket(AF_INET, SOCK_STREAM, 0);\n    "
    "    if (sock < 0) return lamo_make_string(\"\");\n        he = gethostbyname(host);\n        if (!he) { close(sock); ret"
    "urn lamo_make_string(\"\"); }\n        addr.sin_family = AF_INET;\n        addr.sin_port = htons((unsigned short)port);"
    "\n        addr.sin_addr = *((struct in_addr*)he->h_addr);\n        if (connect(sock, (struct sockaddr*)&addr, sizeof(add"
    "r)) < 0) {\n            close(sock); return lamo_make_string(\"\");\n        }\n        req_len = strlen(body) + 1024;\n"
    "        request = (char*)malloc(req_len);\n        snprintf(request, req_len,\n                 \"POST %s HTTP/1.1\\r\\n"
    "Host: %s\\r\\nContent-Type: text/plain\\r\\nContent-Length: %zu\\r\\nConnection: close\\r\\nUser-Agent: lamo-http/1.0\\r"
    "\\n\\r\\n%s\",\n                 path, host, strlen(body), body);\n        send(sock, request, strlen(request), 0);\n   "
    "     free(request);\n        while ((chunk_n = recv(sock, chunk, sizeof(chunk), 0)) > 0) {\n            if (buf_len + ch"
    "unk_n + 1 > buf_cap) {\n                while (buf_len + chunk_n + 1 > buf_cap) buf_cap = buf_cap ? buf_cap * 2 : 8192;"
    "\n                buf = (char*)realloc(buf, buf_cap);\n            }\n            memcpy(buf + buf_len, chunk, chunk_n);"
    "\n            buf_len += chunk_n;\n        }\n        close(sock);\n        if (!buf) return lamo_make_string(\"\");\n  "
    "      buf[buf_len] = '\\0';\n        resp_body = strstr(buf, \"\\r\\n\\r\\n\");\n        if (!resp_body) { free(buf); re"
    "turn lamo_make_string(\"\"); }\n        resp_body += 4;\n        {\n            LamoValue v = lamo_std_string(strdup(res"
    "p_body));\n            free(buf);\n            return v;\n        }\n#endif\n    }\n}\n\n#endif /* LAMO_NEEDS_STD_RUNTIM"
    "E */\n\n#endif /* LAMO_RUNTIME_H */\n"
;
